// After "Update Reason for Contact"
// Uses:
// - AI classification from "Analyze Category"
// - Original form selection from "Get Form Submissions"
// - Current lifecycle stage from HubSpot response
//
// Purpose:
// - Normalize original form selection
// - Map AI classification to HubSpot lifecycle stage
// - Detect partner inquiries, including Avoma/n8n reclassification cases
// - Emit routing flags for downstream IF nodes
// - Avoid breaking the existing Speak with Sales branch

const aiClassification = String($('Analyze Category').item.json.output || '').trim();

// Original selection label, if the user picked a reason on the form
const originalLabel =
  $('Get Form Submissions').item.json.body?.properties?.reason_for_contact?.versions?.[0]?.['source-label']
  ?? $('Get Form Submissions').item.json.body?.properties?.reason_for_contact?.value
  ?? '';

// Source/form context, if available
const formName =
  $('Get Form Submissions').item.json.body?.formName
  ?? $('Get Form Submissions').item.json.body?.pageName
  ?? $('Get Form Submissions').item.json.body?.properties?.recent_conversion_event_name?.value
  ?? '';

const message =
  $('Get Form Submissions').item.json.body?.properties?.message?.value
  ?? '';

const email =
  $('Get Form Submissions').item.json.body?.properties?.email?.value
  ?? '';

function normalizeText(val) {
  return String(val || '').toLowerCase().trim();
}

function normalizeOriginalSelection(val) {
  const v = normalizeText(val);

  if (!v) return '';

  if (v.includes('speak') || v.includes('sales')) return 'Speak with Sales';

  if (
    v.includes('partner') ||
    v.includes('partnership') ||
    v.includes('alliance') ||
    v.includes('alliances') ||
    v.includes('channel')
  ) {
    return 'Partnership Enquiry';
  }

  if (v.includes('press') || v.includes('media') || v.includes('journalist')) return 'Press Enquiry';

  if (
    v.includes('career') ||
    v.includes('job') ||
    v.includes('employment') ||
    v.includes('candidate') ||
    v.includes('resume') ||
    v.includes('cv')
  ) {
    return 'Career Enquiry';
  }

  if (v.includes('support') || v.includes('customer')) return 'Customer Support';

  if (v.includes('verification') || v.includes('verify')) return 'Employment Verification';

  return 'General Enquiry';
}

const originalNormalized = normalizeOriginalSelection(originalLabel);

// HubSpot internal lifecycle stage option values
const HS_LIFECYCLE = {
  MQL: 'marketingqualifiedlead',
  OTHER: '1141555748',
  PARTNERSHIP: '58620755',
};

function targetLifecycleFromClassification(c) {
  switch (c) {
    case 'Speak with Sales':
      return HS_LIFECYCLE.MQL;

    case 'Partnership Enquiry':
    case 'Partnership / Alliance Inquiry':
    case 'Contact Us Partner Inquiry':
      return HS_LIFECYCLE.PARTNERSHIP;

    case 'General Enquiry':
    case 'Press Enquiry':
    case 'Career Enquiry':
    case 'Customer Support':
    case 'Employment Verification':
      return HS_LIFECYCLE.OTHER;

    default:
      return null;
  }
}

const targetLifecycleValue = targetLifecycleFromClassification(aiClassification);

// Current lifecycle from the HubSpot node output immediately before this code node
const currentLifecycleValue =
  $json?.properties?.lifecyclestage?.value
  ?? $json?.properties?.lifecyclestage
  ?? '';

const classificationChanged =
  Boolean(originalNormalized) &&
  Boolean(aiClassification) &&
  originalNormalized !== aiClassification;

const lowerOriginalLabel = normalizeText(originalLabel);
const lowerFormName = normalizeText(formName);
const lowerMessage = normalizeText(message);

const originalSelectedPartner =
  lowerOriginalLabel.includes('partner') ||
  lowerOriginalLabel.includes('partnership') ||
  lowerOriginalLabel.includes('alliance') ||
  lowerOriginalLabel.includes('alliances') ||
  lowerOriginalLabel.includes('channel');

const sourceLooksPartner =
  lowerFormName.includes('partner') ||
  lowerFormName.includes('partnership') ||
  lowerFormName.includes('alliance') ||
  lowerFormName.includes('alliances');

const messageLooksPartner =
  lowerMessage.includes('partner') ||
  lowerMessage.includes('partnership') ||
  lowerMessage.includes('strategic partnership') ||
  lowerMessage.includes('alliance') ||
  lowerMessage.includes('alliances') ||
  lowerMessage.includes('reseller') ||
  lowerMessage.includes('channel partner') ||
  lowerMessage.includes('referral partner') ||
  lowerMessage.includes('integration partner') ||
  lowerMessage.includes('technology integration') ||
  lowerMessage.includes('co-marketing') ||
  lowerMessage.includes('affiliate') ||
  lowerMessage.includes('joint initiative');

const isPartnershipInquiry =
  aiClassification === 'Partnership Enquiry' ||
  aiClassification === 'Partnership / Alliance Inquiry' ||
  aiClassification === 'Contact Us Partner Inquiry' ||
  originalNormalized === 'Partnership Enquiry' ||
  originalSelectedPartner ||
  sourceLooksPartner ||
  messageLooksPartner;

// Only update lifecycle if:
// - target exists
// - current value is not already target
//
// I recommend allowing this even when classification did not change,
// because Avoma submissions may not have a meaningful original reason,
// and partner form submissions should still land in the partnership lifecycle.
const shouldUpdateLifecycleStage =
  Boolean(targetLifecycleValue) &&
  String(currentLifecycleValue) !== String(targetLifecycleValue);

const shouldRouteToPartnerWorkflow = Boolean(isPartnershipInquiry);

const shouldRouteToSalesAI =
  aiClassification === 'Speak with Sales' &&
  !shouldRouteToPartnerWorkflow;

// Melissa Harding HubSpot owner ID
const MELISSA_HARDING_OWNER_ID = '79608276';

return [
  {
    json: {
      email,

      aiClassification,
      originalLabel,
      originalNormalized,
      formName,

      classificationChanged,

      currentLifecycleValue,
      targetLifecycleValue,
      shouldUpdateLifecycleStage,

      isPartnershipInquiry,
      shouldRouteToPartnerWorkflow,
      shouldRouteToSalesAI,

      partnerOwnerId: MELISSA_HARDING_OWNER_ID,

      hubspotUpdate: {
        ...(shouldUpdateLifecycleStage ? { lifecyclestage: targetLifecycleValue } : {}),

        ...(shouldRouteToPartnerWorkflow
          ? {
              hubspot_owner_id: MELISSA_HARDING_OWNER_ID,
              reason_for_contact: 'Partnership Enquiry',
              ai_processed: 'true',
              ai_partner_inquiry_identified: 'true',
              partner_thank_you_email_requested: 'true',
              inbound_ai_classification: aiClassification,
              inbound_original_reason_for_contact: originalLabel,
              inbound_original_form_name: formName,
            }
          : {}),
      },
    },
  },
];
